import React from 'react';
import Highcharts from 'highcharts/highstock';
import HighchartsReact from 'highcharts-react-official';
import { Block } from 'baseui/block';
import { CHART_STYLES } from '../../constants';
import { STOCK_CHART_NAVIGATOR, STOCK_CHART_SCROLLBAR } from '../../utils/stockChartConfig';
import { ProcessedOHLCData } from '../../types/index';

interface WeeklyHighLowChartProps {
  data: ProcessedOHLCData[];
  ticker: string;
  viewType?: 'weekly' | 'monthly';
}

const formatPrice = (value: number): string => {
  if (value >= 1000) return value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (value >= 1) return value.toFixed(2);
  if (value >= 0.01) return value.toFixed(4);
  return value.toFixed(6);
};

export const WeeklyHighLowChart: React.FC<WeeklyHighLowChartProps> = ({ data, ticker, viewType = 'weekly' }) => {
  const highSeries = {
    name: 'High',
    data: data.map(item => ({
      x: item.date.getTime(),
      y: item.high,
      highDate: item.highDate,
      custom: { highDate: item.highDate }
    })),
    type: 'line' as const,
    color: '#dc2626', // red
    showInNavigator: true,
  };

  const lowSeries = {
    name: 'Low',
    data: data.map(item => ({
      x: item.date.getTime(),
      y: item.low,
      lowDate: item.lowDate,
      custom: { lowDate: item.lowDate }
    })),
    type: 'line' as const,
    color: '#16a34a', // green
    showInNavigator: true,
  };

  const chartOptions = {
    title: { text: `${ticker} - ${viewType === 'weekly' ? 'Weekly' : 'Monthly'} High/Low` },
    credits: { enabled: false },
    chart: {
      backgroundColor: CHART_STYLES.colors.background,
      borderRadius: 8,
      spacing: [20, 20, 20, 20],
      height: 500,
      zooming: { mouseWheel: false },
    },
    xAxis: {
      type: 'datetime',
      title: { text: 'Date', style: CHART_STYLES.axisTitle },
      labels: { style: CHART_STYLES.axisLabels },
      gridLineColor: CHART_STYLES.colors.gridLine,
      lineColor: CHART_STYLES.colors.line,
      tickColor: CHART_STYLES.colors.tick
    },
    yAxis: {
      opposite: false,
      title: {
        text: 'Price',
        align: 'middle',
        rotation: -90,
        x: -10,
        style: CHART_STYLES.axisTitle
      },
      labels: {
        formatter: function (this: { value: number }) {
          return formatPrice(this.value);
        },
        style: CHART_STYLES.axisLabels
      },
      gridLineColor: CHART_STYLES.colors.gridLine,
      lineColor: CHART_STYLES.colors.line
    },
    rangeSelector: { enabled: false },
    navigator: STOCK_CHART_NAVIGATOR,
    scrollbar: STOCK_CHART_SCROLLBAR,
    tooltip: {
      shared: true,
      crosshairs: true,
      useHTML: true,
      backgroundColor: CHART_STYLES.colors.tooltipBackground,
      borderColor: CHART_STYLES.colors.tooltipBackground,
      borderRadius: 6,
      style: CHART_STYLES.tooltip,
      formatter: function (this: { x: number; points?: Array<{ y: number; series: { name: string; color: string }; point: { custom?: { highDate?: Date; lowDate?: Date } } }> }) {
        const dateStr = Highcharts.dateFormat('%e %b %Y', this.x);
        let html = `<div style="font-size: 12px; color: #ffffff;"><strong>${viewType === 'weekly' ? 'Week' : 'Month'} of ${dateStr}</strong><br/>`;
        const pts = (this.points || []).slice().sort((a: any, b: any) => (b.y as number) - (a.y as number));
        pts.forEach((p: any) => {
          const priceStr = formatPrice(p.y);
          html += `<span style="color:${p.series.color}">●</span> ${p.series.name}: <strong>${priceStr}</strong>`;
          
          // Add date information
          if (p.series.name === 'High' && p.point.custom?.highDate) {
            const highDateStr = Highcharts.dateFormat('%e %b %Y', p.point.custom.highDate.getTime());
            html += ` (${highDateStr})`;
          } else if (p.series.name === 'Low' && p.point.custom?.lowDate) {
            const lowDateStr = Highcharts.dateFormat('%e %b %Y', p.point.custom.lowDate.getTime());
            html += ` (${lowDateStr})`;
          }
          
          html += '<br/>';
        });
        return html + '</div>';
      },
    },
    plotOptions: {
      series: {
        animation: false,
        marker: {
          enabled: false,
          states: { hover: { enabled: true, radius: 5 } }
        },
      }
    },
    series: [highSeries, lowSeries],
    legend: {
      enabled: true,
      itemStyle: CHART_STYLES.legend,
      itemHoverStyle: { color: '#1f2937' },
    },
  };

  return (
    <Block marginTop="1.5rem">
      <HighchartsReact
        highcharts={Highcharts}
        constructorType="stockChart"
        options={chartOptions}
        immutable
      />
    </Block>
  );
};